function dataUrlToBinary(dataUrl, fileName) {
  if (!dataUrl || typeof dataUrl !== 'string') return null;
  const match = dataUrl.match(/^data:([^;]+);base64,(.+)$/);
  if (!match) return null;
  return {
    data: match[2],
    mimeType: match[1],
    fileName,
    fileExtension: (match[1].split('/')[1] || 'bin'),
  };
}

return items.map((item) => {
  const body = (item.json && item.json.body) || item.json || {};
  const binary = {};
  const qr = dataUrlToBinary(body.qrDataUrl, 'undefined-pass.png');
  const sig = dataUrlToBinary(body.signatureDataUrl, 'undefined-signature.png');
  if (qr) binary.qr = qr;
  if (sig) binary.signature = sig;
  return { json: item.json, binary };
});

// Drop duplicate `agree` submissions for the same payloadHash (or email
// fallback) within a 2-minute window. This is a server-side belt-and-braces
// to the client-side submit-button debounce in src/main.js — it catches
// double-taps from multiple devices, retried network requests, and other
// cases where the same submission lands twice.
//
// State is kept in workflow static data (per-workflow, persisted across
// executions). This is best-effort: two truly simultaneous executions
// could both pass the check before either stores its timestamp, but the
// real-world race window is small and the client-side debounce already
// covers single-device double-taps.

const WINDOW_MS = 2 * 60 * 1000;
const staticData = $getWorkflowStaticData('global');
const recent = staticData.recentAgrees || {};
const now = Date.now();

for (const [key, ts] of Object.entries(recent)) {
  if (typeof ts !== 'number' || now - ts > WINDOW_MS) {
    delete recent[key];
  }
}

const passThrough = [];
for (const item of items) {
  const body = (item.json && item.json.body) || {};
  const acceptance = body.acceptance || {};
  const hash = typeof acceptance.payloadHash === 'string' ? acceptance.payloadHash : '';
  const email = typeof acceptance.email === 'string' ? acceptance.email.trim().toLowerCase() : '';
  const key = hash || (email ? `email:${email}` : '');

  if (!key) {
    passThrough.push(item);
    continue;
  }

  const lastSeen = recent[key];
  if (typeof lastSeen === 'number' && now - lastSeen < WINDOW_MS) {
    console.log(`[dedupe] dropping duplicate agree (key=${key}, age=${now - lastSeen}ms)`);
    continue;
  }

  recent[key] = now;
  passThrough.push(item);
}

staticData.recentAgrees = recent;
return passThrough;
